<script setup lang="ts">
import {computed,inject,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {adminSessionKey} from './adminSession';
import {units4,decimal4} from './portalAmounts';
import {paymentConfirmManualPostApiV1AdminPaymentsRechargesIdConfirm as confirmReceipt,paymentRejectManualPostApiV1AdminPaymentsRechargesIdReject as rejectReceipt,billingEntriesGetApiV1BillingWalletsKeyIdLedger as readLedger,type ResponsePaymentInterfacesHttpPaymentControllerAdminOrder as Record,type ResponseUserApplicationIdentityAdminUserDirectoryItem as User} from './api';
import PromoterIcon from './PromoterIcon.vue';
const props=defineProps<{record:Record;user?:User;review:boolean}>(),emit=defineEmits<{close:[];changed:[]}>();
const session=inject(adminSessionKey),allowed=computed(()=>['ADMIN','NORMAL_ADMIN'].includes(session?.currentAdmin.value?.role||''));
const order=computed(()=>props.record.order!),localStatus=ref<string|null>(null),fulfilled=ref(false),busy=ref(false),error=ref(''),copied=ref('');
const dialog=ref<HTMLDialogElement>();
const entries=ref<Awaited<ReturnType<typeof readLedger>>['data']>([]);
let alive=true,version=0;
const currentStatus=computed(()=>localStatus.value||order.value.status);
const canReview=computed(()=>allowed.value&&props.review&&order.value.source==='MANUAL'&&currentStatus.value==='REVIEW_PENDING');
const state=computed(()=>currentStatus.value==='PAID'?(localStatus.value?fulfilled.value:order.value.fulfilled)?'已到账':'入账中':({REVIEW_PENDING:'待审核',REJECTED:'已驳回',PENDING:'待支付',REFUNDED:'已退款',REFUND_PENDING:'退款处理中',EXPIRED:'已过期'} as {[name:string]:string})[currentStatus.value||'']||'—');
const user=computed(()=>props.user?.id===order.value.userId?props.user:null);
const account=computed(()=>({PERSONAL:'个人账户',ENTERPRISE:'企业账户',API:'API 账户'}[order.value.accountType||'']||'—'));
const method=computed(()=>order.value.source==='CORPORATE'?'对公转账':order.value.source==='MANUAL'?'人工充值':order.value.paymentMethod==='WECHAT'?'微信支付':order.value.paymentMethod==='ALIPAY'?'支付宝':'线上支付');
const source=computed(()=>({NATURAL:'自然注册',REFERRAL:'代理推荐',ADMIN:'管理员添加'}[user.value?.source||'']||'—'));
const kind=computed(()=>'人工增加');
const cash=(v?:string|null)=>{if(units4(v)===null)return '—';const[w,f='']=v!.split('.');return w!.replace(/\B(?=(\d{3})+(?!\d))/g,',')+'.'+f.padEnd(2,'0').slice(0,2);};
const time=(v?:string|null)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—';
const afterPoints=computed(()=>{const before=units4(user.value?.availablePoints4),amount=units4(order.value.expectedPoints4);return before===null||amount===null?null:decimal4(before+amount);});
const balances=computed(()=>{const matches=entries.value.filter(e=>e.kind==='RECHARGE'&&e.requestId===order.value.orderId&&units4(e.points4)===units4(order.value.expectedPoints4));if(matches.length!==1)return null;const e=matches[0]!,after=units4(e.balanceAfter4),points=units4(e.points4),rate=units4(order.value.rateSnapshot4);if(after===null||points===null||points<=0n||rate===null||rate<=0n||after<points)return null;return {before:decimal4((after-points)*10000n/rate),after:decimal4(after*10000n/rate)};});
async function copy(value?:string|null){if(!value)return;try{await navigator.clipboard.writeText(value);if(alive)copied.value=value;}catch{if(alive)error.value='复制失败，请重试。';}}
function close(){if(busy.value)return;dialog.value?.close();emit('close');}
async function decide(approve:boolean){if(!canReview.value||busy.value||!order.value.orderId)return;const id=order.value.orderId,own=version;busy.value=true;error.value='';try{const result=await(approve?confirmReceipt(id):rejectReceipt(id));if(!alive||own!==version)return;if(result.data.orderId!==id||result.data.userId!==order.value.userId)throw Error('mismatched result');localStatus.value=result.data.status;fulfilled.value=result.data.fulfilled;emit('changed');}catch{if(alive&&own===version)error.value='审核失败或结果未确认，请刷新后重试。';}finally{if(alive&&own===version)busy.value=false;}}
async function init(){if(!allowed.value)return;await nextTick();if(!alive)return;dialog.value?.showModal();if(props.record.keyId){const own=version;try{const r=await readLedger(props.record.keyId,{limit:100});if(alive&&own===version)entries.value=r.data;}catch{/* Missing historical ledger facts remain unknown. */}}}
watch(()=>props.record,()=>{localStatus.value=null;});
watch(()=>[session?.currentAdmin.value?.username,session?.currentAdmin.value?.userId,session?.currentAdmin.value?.role],()=>{version++;entries.value=[];emit('close');});
onMounted(()=>void init());onBeforeUnmount(()=>{alive=false;version++;});
</script>
<template><dialog v-if="allowed" ref="dialog" class="finance-drawer" :aria-label="review?'审核详情':'订单详情'" @cancel.prevent="close" @click="event=>{if(event.target===dialog)close()}"><header><h2>{{review?'审核详情':'订单详情'}}</h2><button type="button" :disabled="busy" :aria-label="review?'关闭审核详情':'关闭订单详情'" autofocus @click="close">×</button></header><div class="finance-drawer-body"><p v-if="error" role="alert" class="finance-error">{{error}}</p><div class="finance-detail-state"><span class="finance-pill" :class="currentStatus==='PAID'?'green':currentStatus==='REJECTED'?'red':'orange'">● {{state}}</span><span v-if="review" class="finance-detail-number">申请编号 <code>{{order.orderId}}</code><button type="button" aria-label="复制申请编号" @click="copy(order.orderId)"><PromoterIcon name="copy"/></button></span></div>
<template v-if="!review"><strong class="finance-detail-amount">¥ {{cash(order.amount4)}}</strong><dl class="finance-detail-fields"><dt>订单号</dt><dd class="finance-copy-field"><code>{{order.orderId}}</code><button type="button" aria-label="复制订单号" @click="copy(order.orderId)"><PromoterIcon name="copy"/></button></dd><dt>创建时间</dt><dd>{{time(order.createdAt)}}</dd><dt>支付时间</dt><dd>{{time(record.paidAt)}}</dd></dl></template>
<div v-else class="finance-detail-kind"><span class="finance-pill blue">{{kind}}</span></div>
<section><h3>{{review?'申请信息':'用户信息'}}</h3><dl class="finance-detail-fields"><dt>用户名</dt><dd>{{user?.nickname||'—'}}</dd><dt>手机号</dt><dd>{{user?.phone||'—'}}</dd><dt>账户类型</dt><dd>{{account}}</dd><template v-if="review"><dt>用户来源</dt><dd><span class="finance-pill source">{{source}}</span></dd><dt>申请金额</dt><dd>¥ {{cash(order.amount4)}}</dd><dt>申请人</dt><dd>{{order.submittedBy||'—'}}</dd><dt>申请时间</dt><dd>{{time(order.createdAt)}}</dd><dt>申请备注</dt><dd>{{order.remark||'—'}}</dd></template></dl></section>
<template v-if="!review"><section><h3>金额信息</h3><dl class="finance-detail-fields"><dt>订单金额</dt><dd>¥ {{cash(order.amount4)}}</dd><dt>实付金额</dt><dd>{{record.paidAt?'¥ '+cash(order.amount4):'—'}}</dd><dt>到账金额</dt><dd>{{order.fulfilled?'¥ '+cash(order.amount4):'—'}}</dd><dt>到账积分</dt><dd>{{order.fulfilled?cash(order.expectedPoints4):'—'}}</dd></dl></section><section><h3>支付信息</h3><dl class="finance-detail-fields"><dt>支付方式</dt><dd><span class="finance-pill blue">{{method}}</span></dd><dt>支付流水号</dt><dd class="finance-copy-field"><code>{{record.transactionId||'—'}}</code><button v-if="record.transactionId" type="button" aria-label="复制支付流水号" @click="copy(record.transactionId)"><PromoterIcon name="copy"/></button></dd><dt>支付渠道</dt><dd>{{order.source==='PROVIDER'?'收钱吧':method}}</dd><dt>支付状态</dt><dd>{{state}}</dd><dt v-if="record.refundReference">退款流水号</dt><dd v-if="record.refundReference">{{record.refundReference}}</dd></dl></section><section aria-label="账户变动"><h3>账户变动</h3><dl class="finance-detail-fields"><dt>支付前余额</dt><dd>{{balances?'¥ '+cash(balances.before):'—'}}</dd><dt>本次到账</dt><dd>{{order.fulfilled?'+ ¥ '+cash(order.amount4):'—'}}</dd><dt>支付后余额</dt><dd>{{balances?'¥ '+cash(balances.after):'—'}}</dd></dl></section></template>
<section v-if="review"><h3>到账信息</h3><dl class="finance-detail-fields"><dt>充值方式</dt><dd>{{method}}</dd><dt>确认时间</dt><dd>{{time(record.paidAt)}}</dd><dt>审核人</dt><dd>{{order.confirmedBy||order.rejectedBy||'—'}}</dd><dt v-if="record.transactionId">支付流水号</dt><dd v-if="record.transactionId">{{record.transactionId}}</dd></dl></section>
<template v-if="review"><section><h3>金额核对</h3><dl class="finance-detail-fields"><dt>申请金额</dt><dd :title="order.amount4||undefined">¥ {{cash(order.amount4)}}</dd><dt>{{record.paidAt?'已确认金额':'待核实金额'}}</dt><dd>¥ {{cash(order.amount4)}}</dd></dl></section><section v-if="canReview" class="finance-balance-preview"><h3>余额变化预览</h3><div><span>当前积分<strong>{{cash(user?.availablePoints4)}}</strong></span><b>→</b><span>本次到账积分<strong>+ {{cash(order.expectedPoints4)}}</strong></span><b>→</b><span>审核后积分<strong>{{cash(afterPoints)}}</strong></span></div></section></template>
<section class="finance-audit"><h3>操作记录</h3><ol><li v-if="order.rejectedAt"><time>{{time(order.rejectedAt)}}</time><div><strong>申请已驳回</strong><p>{{order.rejectedBy||'—'}}</p></div></li><li v-if="record.paidAt"><time>{{time(record.paidAt)}}</time><div><strong>支付已确认</strong><p>{{order.confirmedBy||method}}，¥ {{cash(order.amount4)}}</p><p>{{order.fulfilled?'已到账':'入账中'}}</p></div></li><li><time>{{time(order.createdAt)}}</time><div><strong>{{review?'提交申请':'创建订单'}}</strong><p>金额 ¥ {{cash(order.amount4)}}</p></div></li></ol></section>
</div><footer v-if="canReview" class="finance-review-actions"><button type="button" :disabled="busy" @click="decide(false)">驳回申请</button><button type="button" class="finance-primary" :disabled="busy" @click="decide(true)">{{busy?'处理中…':'确认到账并通过'}}</button></footer>
</dialog></template>
